def transform(grid):
    """Compare corresponding cells of two panels divided by a uniform column.

    The unique shared panel color is the output background; matching values
    in corresponding cells are marked with 3.
    """
    h, n = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1

    # The divider is a solid column whose color appears only there.
    divider = next(
        c for c in range(n)
        if all(row[c] == grid[0][c] for row in grid)
        and counts[grid[0][c]] == h
    )
    width = min(divider, n - divider - 1)
    left = [row[:width] for row in grid]
    right = [row[divider + 1:divider + 1 + width] for row in grid]
    shared_colors = {v for row in left for v in row} & {v for row in right for v in row}
    background = next(iter(shared_colors))

    return [
        [3 if left[r][c] == right[r][c] else background for c in range(width)]
        for r in range(h)
    ]
